SELECT mall_order.*, JSON_UNQUOTE(JSON_EXTRACT(mall_product.images, '$[0]')) AS product_image
FROM mall_order LEFT JOIN mall_product ON mall_product.id = mall_order.product_id

ORDER BY mall_order.id DESC LIMIT #{query.size} OFFSET #{offset}

SELECT mall_order.*, JSON_UNQUOTE(JSON_EXTRACT(mall_product.images, '$[0]')) AS product_image
FROM mall_order LEFT JOIN mall_product ON mall_product.id = mall_order.product_id
WHERE mall_order.member_id = #{memberId} ORDER BY mall_order.id DESC LIMIT #{size} OFFSET #{offset}

SELECT mall_order.*, JSON_UNQUOTE(JSON_EXTRACT(mall_product.images, '$[0]')) AS product_image
FROM mall_order LEFT JOIN mall_product ON mall_product.id = mall_order.product_id
WHERE mall_order.id = #{id}

SELECT mall_order.*, JSON_UNQUOTE(JSON_EXTRACT(mall_product.images, '$[0]')) AS product_image
FROM mall_order LEFT JOIN mall_product ON mall_product.id = mall_order.product_id
WHERE mall_order.id = #{id} AND mall_order.member_id = #{memberId}
